    <div className="ex-metrics"><Metric name="Verified earned" value={money(bal.earnedPence)} note="Lifetime, from verified collections"/><Metric name="Available to request" value={money(bal.availablePence)} note="Earned, unallocated and not already requested"/><Metric name="Requested" value={money(bal.requestedPence)} note="Awaiting founder review or payout preparation"/><Metric name="In prepared payout" value={money(bal.preparedPence)} note="Approved for manual settlement"/><Metric name="Paid" value={money(bal.paidPence)} note="Manually settled and recorded"/>{Number(bal.disputedPence)!==0 && <Metric name="Under review" value={money(bal.disputedPence)} note="Potential refund adjustment, not yet decided"/>}</div>
